package dev.kristian.nullmod.client.stalker;

import dev.kristian.nullmod.entity.stalker.StalkerAnimation;
import dev.kristian.nullmod.entity.stalker.StalkerEntity;
import net.minecraft.client.model.HierarchicalModel;
import net.minecraft.client.model.geom.ModelPart;
import net.minecraft.util.Mth;

/**
 * The figure's model and every move it makes, all procedural. The geometry is
 * {@link StalkerModelLayer} (generated by {@code tools/gen_stalkers.py}, whose preview poser mirrors
 * {@link #apply} formula for formula). It stands slightly stooped with its arms hanging to its
 * shins, leans out from behind things with its fingers round the edge, raises a hand to a window,
 * swings an old pickaxe, stoops under low ceilings, walks with long slow strides and, for the
 * runner of the NULL stage, sprints with its arms trailing behind.
 * <p>
 * Model space is in pixels: +X is its left, +Y down, -Z its front, the ground at y = 24. Render
 * thread only.
 */
public final class StalkerModel extends HierarchicalModel<StalkerEntity> {
    static final float BODY_LEAN = 0.10F;
    static final float NECK_BEND = 0.18F;
    static final float HEAD_LIFT = -0.26F;
    static final float SWING_READY = -0.95F;
    static final float SWING_RAISED = -3.35F;
    static final float SWING_HIT = -1.35F;
    /** Swing phase at which the blow lands (between the lift and the rest). */
    static final float SWING_BLOW = 0.68F;

    /** Everything a pose depends on (StalkerFigure fills one directly for the runner). */
    public static final class Pose {
        /** Stride phase in radians. */
        public float walk;
        /** 0..1 how much it walks. */
        public float walkAmount;
        /** 0..1 sprinting. */
        public float run;
        /** -1..1 leaning out to its right (-) or left (+). */
        public float peek;
        /** 0..1 holding the pickaxe ready. */
        public float dig;
        /** 0..1 through one swing (0 between swings). */
        public float digPhase;
        /** 0..1 one hand flat against a window. */
        public float glass;
        /** 0..1 stooped under a low ceiling. */
        public float hunch;
        /** Radians, relative to the body. */
        public float headYaw;
        public float headPitch;
        /** 0..1 a sudden twitch of the head. */
        public float twitch;
        /** Ticks, for breathing. */
        public float time;
        public boolean pickaxe;

        public void clear() {
            walk = 0.0F;
            walkAmount = 0.0F;
            run = 0.0F;
            peek = 0.0F;
            dig = 0.0F;
            digPhase = 0.0F;
            glass = 0.0F;
            hunch = 0.0F;
            headYaw = 0.0F;
            headPitch = 0.0F;
            twitch = 0.0F;
            time = 0.0F;
            pickaxe = false;
        }
    }

    private final ModelPart root;
    private final ModelPart hips;
    private final ModelPart body;
    private final ModelPart neck;
    private final ModelPart head;
    private final ModelPart pickaxe;
    /** Index 0 is its right side, 1 its left. */
    private final ModelPart[] arm = new ModelPart[2];
    private final ModelPart[] forearm = new ModelPart[2];
    private final ModelPart[] fingers = new ModelPart[2];
    private final ModelPart[] thigh = new ModelPart[2];
    private final ModelPart[] shin = new ModelPart[2];
    private final ModelPart[] foot = new ModelPart[2];
    private final Pose pose = new Pose();

    public StalkerModel(ModelPart root) {
        this.root = root;
        this.hips = root.getChild("hips");
        this.body = hips.getChild("body");
        this.neck = body.getChild("neck");
        this.head = neck.getChild("head");
        String[] sides = {"right", "left"};
        for (int s = 0; s < 2; s++) {
            arm[s] = body.getChild("arm_" + sides[s]);
            forearm[s] = arm[s].getChild("forearm_" + sides[s]);
            ModelPart hand = forearm[s].getChild("hand_" + sides[s]);
            fingers[s] = hand.getChild("fingers_" + sides[s]);
            thigh[s] = hips.getChild("thigh_" + sides[s]);
            shin[s] = thigh[s].getChild("shin_" + sides[s]);
            foot[s] = shin[s].getChild("foot_" + sides[s]);
        }
        this.pickaxe = forearm[0].getChild("hand_right").getChild("pickaxe");
    }

    @Override
    public ModelPart root() {
        return root;
    }

    @Override
    public void setupAnim(StalkerEntity entity, float limbSwing, float limbSwingAmount, float ageInTicks, float netHeadYaw, float headPitch) {
        float partial = Mth.clamp(ageInTicks - entity.tickCount, 0.0F, 1.0F);
        StalkerAnimation a = entity.animation;
        pose.clear();
        // Long legs: a slower cadence than a player's for the same speed.
        pose.walk = limbSwing * 0.5F;
        pose.walkAmount = Mth.clamp(limbSwingAmount * 1.4F, 0.0F, 1.0F);
        pose.peek = Mth.lerp(partial, a.peekO, a.peek);
        pose.glass = Mth.lerp(partial, a.glassO, a.glass);
        pose.dig = Mth.lerp(partial, a.digO, a.dig);
        pose.hunch = Mth.lerp(partial, a.hunchO, a.hunch);
        pose.twitch = Mth.lerp(partial, a.twitchO, a.twitch);
        pose.digPhase = a.swingTicks >= 0 ? Mth.clamp((a.swingTicks + partial) / StalkerEntity.SWING_TICKS, 0.0F, 1.0F) : 0.0F;
        pose.pickaxe = pose.dig > 0.02F || entity.act() == StalkerEntity.ACT_DIG;
        pose.headYaw = netHeadYaw * Mth.DEG_TO_RAD;
        pose.headPitch = headPitch * Mth.DEG_TO_RAD;
        pose.time = ageInTicks;
        apply(pose);
    }

    /** Arm angle through one pickaxe swing: a slow lift over the head, a fast blow down in front, a short rest. */
    static float swing(float phase) {
        if (phase < 0.55F) {
            float t = phase / 0.55F;
            return SWING_READY + (SWING_RAISED - SWING_READY) * (t * t * (3.0F - 2.0F * t));
        }
        if (phase < SWING_BLOW) {
            float t = (phase - 0.55F) / (SWING_BLOW - 0.55F);
            return SWING_RAISED + (SWING_HIT - SWING_RAISED) * t * t;
        }
        float t = (phase - SWING_BLOW) / (1.0F - SWING_BLOW);
        return SWING_HIT + (SWING_READY - SWING_HIT) * t * t;
    }

    /** Poses every part (mirrored by {@code pose_model} in tools/gen_stalkers.py). */
    public void apply(Pose p) {
        root.getAllParts().forEach(ModelPart::resetPose);
        float breathe = 0.02F * Mth.sin(p.time * 0.08F);
        float run = p.run;
        float hunch = p.hunch;

        hips.x += 4.0F * p.peek;
        hips.y += 1.5F * hunch + 1.2F * run;
        hips.zRot += -0.08F * p.peek;
        float digLean = p.dig > 0.0F
                ? p.dig * (0.28F - 0.4F * (swing(p.digPhase) - SWING_HIT) / (SWING_RAISED - SWING_HIT))
                : 0.0F;
        body.xRot = BODY_LEAN + breathe + 0.5F * run + 0.42F * hunch + digLean;
        body.zRot = 0.42F * p.peek;
        neck.xRot = NECK_BEND + 0.35F * hunch;
        neck.yRot = p.headYaw * 0.35F;
        head.xRot = HEAD_LIFT - 0.4F * run - 0.6F * hunch + p.headPitch;
        head.yRot = p.headYaw * 0.65F;
        head.zRot = 0.25F * p.peek + 0.3F * p.twitch;

        // Legs: long slow strides, or a sprint.
        float stride = 0.5F * p.walkAmount * (1.0F - run) + 1.05F * run;
        for (int s = 0; s < 2; s++) {
            float phase = p.walk + (s == 0 ? 0.0F : Mth.PI);
            float swing = Mth.sin(phase) * stride;
            float knee = Math.max(0.0F, -Mth.sin(phase - 0.7F)) * (0.7F * p.walkAmount * (1.0F - run) + 1.5F * run);
            thigh[s].xRot = swing - 0.25F * hunch - 0.35F * run;
            shin[s].xRot = knee + 0.45F * hunch;
            foot[s].xRot = -0.2F * knee;
        }
        // Arms: hanging, barely swinging when it walks; trailing behind at a sprint.
        for (int s = 0; s < 2; s++) {
            float sx = s == 0 ? -1.0F : 1.0F;
            float phase = p.walk + (s == 0 ? Mth.PI : 0.0F);
            arm[s].xRot = 0.05F + 0.08F * Mth.sin(phase) * p.walkAmount * (1.0F - run) + run * (0.95F + 0.15F * Mth.sin(phase));
            arm[s].zRot = 0.07F * sx + 0.12F * sx * run;
            forearm[s].xRot = -0.12F - 0.2F * run;
            fingers[s].xRot = 0.15F;
        }
        // Peeking: the near hand comes round the trunk's edge, fingers curled over it.
        if (p.peek != 0.0F) {
            int near = p.peek > 0.0F ? 1 : 0;
            float sx = near == 1 ? 1.0F : -1.0F;
            float amount = Math.abs(p.peek);
            arm[near].xRot += -1.6F * amount;
            arm[near].zRot += -0.82F * sx * amount;
            forearm[near].xRot += -0.58F * amount;
            fingers[near].xRot += 0.95F * amount;
        }
        // Digging: both hands on the handle, the swing from the shoulders.
        if (p.dig > 0.0F) {
            float a = swing(p.digPhase);
            for (int s = 0; s < 2; s++) {
                float sx = s == 0 ? -1.0F : 1.0F;
                arm[s].xRot = Mth.lerp(p.dig, arm[s].xRot, a);
                arm[s].zRot = Mth.lerp(p.dig, arm[s].zRot, -0.3F * sx);
                forearm[s].xRot = Mth.lerp(p.dig, forearm[s].xRot, -0.25F);
                fingers[s].xRot = Mth.lerp(p.dig, fingers[s].xRot, 0.9F);
            }
        }
        // At the window: its left hand raised beside its face, flat to the glass.
        if (p.glass > 0.0F) {
            float g = p.glass;
            arm[1].xRot = Mth.lerp(g, arm[1].xRot, -2.9F);
            arm[1].zRot = Mth.lerp(g, arm[1].zRot, -0.2F);
            forearm[1].xRot = Mth.lerp(g, forearm[1].xRot, 1.9F);
            fingers[1].xRot = Mth.lerp(g, fingers[1].xRot, -0.2F);
        }
        pickaxe.visible = p.pickaxe;
    }
}
